        JSONObject source=store.addMessage("user","selected original record",null);store.getWritableDatabase().execSQL("UPDATE messages SET text='different SQL generation' WHERE id=?",new Object[]{source.getLong("id")});assertThrows(IllegalArgumentException.class,()->delete(source));assertEquals("different SQL generation",store.getMessage(source.getLong("id")).getString("text"));assertEquals(0,store.getPrivacyLedger().version());
